import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        int[] a = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }
        Arrays.sort(a);

        final long INF = Long.MAX_VALUE / 4;
        long[] dp1 = new long[K + 1];
        long[] dp2 = new long[K + 1];
        long[] cur = new long[K + 1];

        Arrays.fill(dp1, INF);
        Arrays.fill(dp2, INF);
        dp1[0] = 0;
        dp2[0] = 0;

        for (int i = N - 1; i >= 0; i--) {
            Arrays.fill(cur, INF);
            int len = N - i;
            int maxP = Math.min(K, len / 3);

            for (int p = 0; p <= maxP; p++) {
                if (dp1[p] < cur[p]) {
                    cur[p] = dp1[p];
                }

                if (p > 0 && i + 1 < N) {
                    long diff = a[i + 1] - a[i];
                    long cost = diff * diff;
                    long val = dp2[p - 1] + cost;
                    if (val < cur[p]) {
                        cur[p] = val;
                    }
                }
            }

            long[] tmp = dp2;
            dp2 = dp1;
            dp1 = cur;
            cur = tmp;
        }

        System.out.println(dp1[K]);
    }
}
